def flatten(nested):
    """Flatten arbitrarily nested iterables using recursion and yield from."""
    for item in nested:
        if isinstance(item, (list, tuple)):
            yield from flatten(item)
        else:
            yield item

class RangeIterator:
    """Custom iterator class implementing __iter__ and __next__ dunder methods."""
    def __init__(self, start, stop):
        self.current = start
        self.stop = stop
    def __iter__(self):
        return self
    def __next__(self):
        if self.current >= self.stop:
            raise StopIteration
        val = self.current
        self.current += 1
        return val

class FiniteIterator:
    def __init__(self, limit):
        self.n = 0
        self.limit = limit
    def __iter__(self):
        return self
    def __next__(self):
        if self.n >= self.limit:
            raise StopIteration("Iteration limit reached")
        self.n += 1
        return self.n

def infinite_sequence(start=0):
    """Generate an unbounded sequence of numbers."""
    num = start
    while True:
        yield num
        num += 1

def read_large_file(file_path):
    """Read file line by line without buffering entire file in RAM."""
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            yield line.strip()

def fibonacci_gen():
    """Infinite Fibonacci number sequence generator."""
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

