def combine_lists(list_a, list_b, list_c):
    """Chain multiple collections into a single continuous iterator."""
    return list(itertools.chain(list_a, list_b, list_c))

import itertools

def get_first_n_items(iterable, n):
    """Extract first n items from an iterator without exhausting the rest."""
    return list(itertools.islice(iterable, n))

