def cumulative_sums(numbers):
    """Calculate running cumulative sums of a numerical sequence."""
    return list(itertools.accumulate(numbers))

import itertools

def group_consecutive(data, key_func):
    """Group sorted data by specified key function."""
    return {k: list(g) for k, g in itertools.groupby(data, key=key_func)}

