def cartesian_product(list1, list2):
    """Compute Cartesian product combinations between two lists."""
    return list(itertools.product(list1, list2))

import itertools

def find_combinations(items, r):
    """Return r-length combinations and permutations of elements."""
    combs = list(itertools.combinations(items, r))
    perms = list(itertools.permutations(items, r))
    return {'combinations': combs, 'permutations': perms}

