def enforce_types(**expected_types):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for name, val in kwargs.items():
                if name in expected_types and not isinstance(val, expected_types[name]):
                    raise TypeError(f"Arg {name} must be {expected_types[name]}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

