class Circle:
    def __init__(self, radius):
        self._radius = radius
    @property
    def radius(self):
        return self._radius
    @radius.setter
    def radius(self, val):
        if val <= 0:
            raise ValueError("Radius must be positive")
        self._radius = val
    @radius.deleter
    def radius(self):
        del self._radius

