from concurrent.futures import ProcessPoolExecutor

def cpu_bound_fib(n):
    if n < 2: return n
    return cpu_bound_fib(n-1) + cpu_bound_fib(n-2)

with ProcessPoolExecutor() as executor:
    results = list(executor.map(cpu_bound_fib, [30, 31, 32]))

