from collections import deque

def bfs(graph, root):
    visited = {root}
    q = deque([root])
    order = []
    while q:
        node = q.popleft()
        order.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                q.append(neighbor)
    return order

