def has_cycle(graph):
    visited = {}  # 0: visiting, 1: visited
    def dfs(node):
        visited[node] = 0
        for nxt in graph.get(node, []):
            if visited.get(nxt) == 0: return True
            if nxt not in visited and dfs(nxt): return True
        visited[node] = 1
        return False
    return any(dfs(n) for n in graph if n not in visited)

